  full_set = excluded.full_set,
  collections = excluded.collections,
  featured = excluded.featured,
  added_at = excluded.added_at,
  tone = excluded.tone,
  position = excluded.position,
  stock = excluded.stock,
  is_active = true
where public.products.updated_by is null;

